<script setup lang="ts">
import { computed, onMounted, onUnmounted, ref, watch } from 'vue'
import { useRoute } from 'vue-router'
import { ArrowLeft, Upload, FolderOpen, X, RotateCw, ChevronLeft, ChevronRight } from 'lucide-vue-next'
import { ElMessage } from 'element-plus'
import { ApiError, errorText } from '../api'
import { knowledge, uploadBatch, fileSize, displayTime, taskStatus, taskStage, type ImportBatch, type ImportTask } from '../knowledge'
import { useAuth } from '../stores/auth'
import { useUnsaved } from '../useUnsaved'
import PageHeader from '../components/PageHeader.vue'
import AsyncState from '../components/AsyncState.vue'
const auth=useAuth(),route=useRoute(),files=ref<{file:File;path:string;key:string}[]>([]),fileInput=ref<HTMLInputElement|null>(null),folderInput=ref<HTMLInputElement|null>(null),dragging=ref(false),category=ref(''),uploading=ref(false),uploadPercent=ref(0),uploadError=ref(''),idempotency=ref(crypto.randomUUID()),batches=ref<ImportBatch[]>([]),selected=ref<ImportBatch|null>(null),loading=ref(true),error=ref(''),detailLoading=ref(false),detailError=ref(''),page=ref(1),total=ref(0),retrying=ref(''),lastRefresh=ref(''),capError=ref('')
const limits=ref({max_files:100,max_file_bytes:50*1024*1024,max_batch_bytes:200*1024*1024,pdf_ocr:false,boundaries:[] as string[]}),capReady=ref(false)
const canRead=computed(()=>auth.has('knowledge:task:read')||auth.has('knowledge:task:read-any'))
const canRetry=computed(()=>['knowledge:import','knowledge:update','knowledge:create'].some(auth.has))
const bytes=computed(()=>files.value.reduce((sum,x)=>sum+x.file.size,0))
const selectionError=computed(()=>files.value.length>limits.value.max_files?`每批最多 ${limits.value.max_files} 个文件。`:files.value.some(x=>x.file.size>limits.value.max_file_bytes)?`存在超过 ${fileSize(limits.value.max_file_bytes)} 的文件，请移除后上传。`:bytes.value>limits.value.max_batch_bytes?`本批文件超过 ${fileSize(limits.value.max_batch_bytes)}，请分批上传。`:'')
const batchLabels:Record<string,string>={pending:'等待处理',processing:'处理中',completed:'全部完成',partial_failed:'部分失败',failed:'失败',cancelled:'已取消'}
useUnsaved(()=>files.value.length>0,()=>uploading.value)
let alive=true,pollTimer:ReturnType<typeof setTimeout>,controller:AbortController|null=null,loadSequence=0,detailSequence=0
function changed(){idempotency.value=crypto.randomUUID();uploadError.value='';uploadPercent.value=0}
function addFiles(list:{file:File;path:string}[]){if(uploading.value)return;for(const item of list){const key=`${item.path}:${item.file.size}:${item.file.lastModified}`;if(!files.value.some(x=>x.key===key))files.value.push({...item,key})}changed()}
function pick(event:Event){const input=event.target as HTMLInputElement;addFiles(Array.from(input.files||[]).map(file=>({file,path:file.webkitRelativePath||file.name})));input.value=''}
async function drop(event:DragEvent){dragging.value=false;if(uploading.value)return;const collected:{file:File;path:string}[]=[];async function walk(entry:FileSystemEntry,path=''):Promise<void>{if(entry.isFile){const file=await new Promise<File>((resolve,reject)=>(entry as FileSystemFileEntry).file(resolve,reject));collected.push({file,path:path+file.name})}else if(entry.isDirectory){const reader=(entry as FileSystemDirectoryEntry).createReader();let entries:FileSystemEntry[];do{entries=await new Promise((resolve,reject)=>reader.readEntries(resolve,reject));for(const child of entries)await walk(child,path+entry.name+'/')}while(entries.length)}}try{const entries=Array.from(event.dataTransfer?.items||[]).map(item=>item.webkitGetAsEntry?.()).filter((x):x is FileSystemEntry=>!!x);if(entries.length){for(const entry of entries)await walk(entry);addFiles(collected)}else addFiles(Array.from(event.dataTransfer?.files||[]).map(file=>({file,path:file.name})))}catch{uploadError.value='部分目录无法读取，请使用选择目录重新添加。'}}
async function loadCapabilities(){capError.value='';try{const r=await knowledge.capabilities();limits.value={max_files:Number(r.max_files)||100,max_file_bytes:Number(r.max_file_bytes)||50*1024*1024,max_batch_bytes:Number(r.max_batch_bytes)||200*1024*1024,pdf_ocr:!!r.pdf_ocr,boundaries:Array.isArray(r.boundaries)?r.boundaries.map(String):[]};capReady.value=true}catch(e){capError.value=errorText(e);capReady.value=false}}
async function loadBatches(silent=false){if(!canRead.value){loading.value=false;return}const s=++loadSequence;if(!silent)loading.value=true;error.value='';try{const r=await knowledge.batches(page.value);if(!alive||s!==loadSequence)return;batches.value=r.items;total.value=r.total;lastRefresh.value=new Date().toISOString();if(!selected.value&&r.items.length){const initial=String(route.query.batch||r.items[0]!.id);await loadBatch(initial)}}catch(e){if(s===loadSequence){batches.value=[];total.value=0;error.value=errorText(e);if(e instanceof ApiError&&[401,403,404].includes(e.status))selected.value=null}}finally{if(s===loadSequence)loading.value=false}}
async function loadBatch(id:string,silent=false){const s=++detailSequence;if(!silent)detailLoading.value=true;detailError.value='';try{const r=await knowledge.batch(id);if(alive&&s===detailSequence){selected.value=r;lastRefresh.value=new Date().toISOString()}}catch(e){if(s===detailSequence){selected.value=null;detailError.value=errorText(e)}}finally{if(s===detailSequence)detailLoading.value=false}}
async function submit(){if(uploading.value||selectionError.value||!files.value.length||!capReady.value)return;uploading.value=true;uploadError.value='';controller=new AbortController();try{const body=new FormData();files.value.forEach(x=>body.append('files',x.file));body.append('relative_paths',JSON.stringify(files.value.map(x=>x.path)));body.append('idempotency_key',idempotency.value);body.append('category',category.value.trim());const batch=await uploadBatch(body,p=>uploadPercent.value=p,controller.signal);files.value=[];changed();selected.value=batch;ElMessage.success('文件已接收，正在后台处理');page.value=1;if(canRead.value)await loadBatches(true)}catch(e){uploadError.value=errorText(e);if(e instanceof ApiError&&e.status===401)await auth.refresh().catch(()=>{})}finally{uploading.value=false;controller=null}}
async function retry(task:ImportTask){retrying.value=task.id;detailError.value='';try{await knowledge.retry(task.id);ElMessage.success('已重新排队');if(selected.value)await loadBatch(selected.value.id,true);await loadBatches(true)}catch(e){detailError.value=errorText(e)}finally{retrying.value=''}}
function progress(task:ImportTask){return Math.max(0,Math.min(100,task.progress?.percent??(task.status==='completed'?100:0)))}
async function poll(){if(!alive)return;if(document.visibilityState==='visible'&&canRead.value&&!uploading.value){await loadBatches(true);if(selected.value)await loadBatch(selected.value.id,true)}if(alive)pollTimer=setTimeout(poll,5000)}
function refresh(){void loadBatches();if(selected.value)void loadBatch(selected.value.id)}
function paging(delta:number){page.value+=delta;void loadBatches()}
watch(()=>auth.permissions.join('|'),()=>{batches.value=[];selected.value=null;if(!auth.has('knowledge:import')){files.value=[];controller?.abort()}void loadBatches()})
onMounted(()=>{void loadCapabilities();void loadBatches();pollTimer=setTimeout(poll,5000)})
onUnmounted(()=>{alive=false;loadSequence++;detailSequence++;clearTimeout(pollTimer);controller?.abort()})
</script>
<template>
 <div class="knowledge-screen import-screen">
 <RouterLink to="/knowledge" class="text-button back-link"><ArrowLeft :size="16"/>返回知识列表</RouterLink>
 <PageHeader title="导入中心" description="上传文档，跟进每个文件的处理结果。"><button class="button" :disabled="loading||uploading" @click="refresh"><RotateCw :size="16"/>刷新</button></PageHeader>
 <section v-if="auth.has('knowledge:import')" class="import-upload-section" aria-label="上传知识文档">
  <div class="upload-zone" :class="{'drag-over':dragging,'is-busy':uploading}" @dragover.prevent="dragging=true" @dragleave.prevent="dragging=false" @drop.prevent="drop"><Upload :size="24" :stroke-width="1.5"/><div><h2>{{uploading?'正在上传文件':files.length?`已选择 ${files.length} 个文件`:'将文档或目录拖到这里'}}</h2><p class="muted">PDF、Word .docx、Markdown、TXT</p></div><div class="upload-controls"><button class="button" :disabled="uploading" @click="fileInput?.click()">选择文件</button><button class="button" :disabled="uploading" @click="folderInput?.click()"><FolderOpen :size="16"/>选择目录</button></div><input ref="fileInput" type="file" multiple class="sr-only" tabindex="-1" aria-label="选择导入文件" @change="pick"/><input ref="folderInput" type="file" multiple webkitdirectory class="sr-only" tabindex="-1" aria-label="选择导入目录" @change="pick"/></div>
  <div class="import-boundaries"><span>文字 PDF 可直接导入；{{limits.pdf_ocr?'扫描 PDF 已启用 OCR。':'扫描 PDF 需先识别文字。'}}旧 .doc 请另存为 .docx。</span><span v-if="capReady" class="num">每批 {{limits.max_files}} 个 · 单文件 {{fileSize(limits.max_file_bytes)}} · 合计 {{fileSize(limits.max_batch_bytes)}}</span></div>
  <p v-if="capError" class="form-error" role="alert">上传能力暂不可用：{{capError}} <button class="text-button" @click="loadCapabilities">重试</button></p>
  <div v-if="files.length" class="selected-files"><div class="section-heading"><h3>待上传文件 · {{fileSize(bytes)}}</h3><button class="text-button" :disabled="uploading" @click="files=[];changed()">清空</button></div><ul><li v-for="(entry,index) in files" :key="entry.key"><span class="selected-file-name">{{entry.path}}</span><span class="muted num">{{fileSize(entry.file.size)}}</span><button class="icon-button" :aria-label="`移除 ${entry.path}`" :disabled="uploading" @click="files.splice(index,1);changed()"><X :size="16"/></button></li></ul><div class="upload-footer"><div class="upload-category"><label for="import-category">统一分类</label><input id="import-category" v-model="category" maxlength="100" placeholder="可选" :disabled="uploading" @input="changed"/></div><span class="muted">同名文档会分别保留。</span><button class="button primary" :disabled="uploading||!!selectionError||!capReady" @click="submit">{{uploading?`正在上传 ${uploadPercent}%`:`开始导入 ${files.length} 个文件`}}</button></div><div v-if="uploading" class="transfer-progress" role="progressbar" :aria-valuenow="uploadPercent" aria-valuemin="0" aria-valuemax="100" aria-label="文件上传进度"><span :style="{width:`${uploadPercent}%`}"></span></div><p v-if="selectionError" class="form-error" role="alert">{{selectionError}}</p></div>
  <p v-if="uploadError" class="form-error" role="alert">{{uploadError}}</p>
 </section>
 <section class="import-jobs" aria-label="导入记录"><div class="section-heading"><div><h2>导入记录</h2><p class="muted">{{canRead?'记录会自动刷新。版本就绪后，请进入知识详情激活并发布。':'当前账号缺少任务查询权限，提交后的任务由后台继续处理。'}}</p></div><span v-if="lastRefresh" class="muted num refresh-stamp">更新于 {{displayTime(lastRefresh)}}</span></div>
 <AsyncState :loading="loading" :error="error" :empty="!batches.length&&!selected" empty-text="还没有导入记录" @retry="loadBatches()"><template #empty><p>上传文档后，可在这里查看进度和处理结果。</p></template>
  <div class="import-job-grid"><aside v-if="batches.length" class="batch-pane" aria-label="选择导入批次"><div class="mobile-batch-picker"><label for="mobile-batch">导入批次</label><select id="mobile-batch" :value="selected?.id" @change="loadBatch(($event.target as HTMLSelectElement).value)"><option v-for="batch in batches" :key="batch.id" :value="batch.id">{{displayTime(batch.created_at)}} · {{batch.file_count}} 个文件 · {{batchLabels[batch.status]||batch.status}}</option></select></div><button v-for="batch in batches" :key="batch.id" class="batch-row" :class="{active:selected?.id===batch.id}" :aria-pressed="selected?.id===batch.id" @click="loadBatch(batch.id)"><span><strong>{{batch.file_count}} 个文件</strong><span class="batch-state">{{batchLabels[batch.status]||batch.status}}</span></span><small>{{displayTime(batch.created_at)}} · {{batch.counts.completed||0}} 完成<span v-if="batch.counts.failed"> · {{batch.counts.failed}} 失败</span></small></button><div class="pagination"><span class="muted num">共 {{total}} 批</span><div><button class="icon-button" aria-label="上一页批次" :disabled="page===1||loading" @click="paging(-1)"><ChevronLeft :size="16"/></button><span class="num">{{page}}</span><button class="icon-button" aria-label="下一页批次" :disabled="page*10>=total||loading" @click="paging(1)"><ChevronRight :size="16"/></button></div></div></aside>
  <div class="batch-detail"><AsyncState :loading="detailLoading" :error="detailError" @retry="selected?loadBatch(selected.id):loadBatches()"><template v-if="selected"><div class="batch-summary"><h3>{{selected.file_count}} 个文件 · {{batchLabels[selected.status]||selected.status}}</h3><div class="batch-counts"><span>完成 {{selected.counts.completed||0}}</span><span>处理中 {{(selected.counts.pending||0)+(selected.counts.processing||0)}}</span><span :class="{'danger-text':selected.counts.failed}">失败 {{selected.counts.failed||0}}</span></div></div><ul class="task-list"><li v-for="task in selected.tasks" :key="task.id"><div class="task-heading"><strong>{{task.file_name||'受限任务'}}</strong><span class="task-status" :class="{'danger-text':task.status==='failed','success-text':task.status==='completed'}">{{taskStatus[task.status]||task.status}}</span></div><p v-if="task.relative_path&&task.relative_path!==task.file_name" class="task-path muted">{{task.relative_path}}</p><div class="task-progress-row"><span class="muted">{{taskStage[task.stage]||task.stage}}</span><span v-if="task.progress" class="num muted">{{progress(task)}}%</span></div><div v-if="task.progress" class="task-progress" role="progressbar" :aria-label="`${task.file_name} 处理进度`" :aria-valuenow="progress(task)" aria-valuemin="0" aria-valuemax="100"><span :style="{width:`${progress(task)}%`}" :class="{'failed-progress':task.status==='failed'}"></span></div><p v-if="task.error_message" class="task-error">{{task.error_message}}</p><p v-for="warning in task.progress?.warnings||[]" :key="warning" class="task-warning">{{warning}}</p><div class="task-footer"><span class="muted num">{{task.file_size!=null?fileSize(task.file_size):'文件信息受限'}}<template v-if="task.attempts"> · 已尝试 {{task.attempts}} 次</template><template v-if="task.progress?.chunk_count!=null"> · {{task.progress.chunk_count}} 个切片</template></span><div><button v-if="task.can_retry&&canRetry" class="text-button" :disabled="!!retrying" @click="retry(task)">{{retrying===task.id?'正在排队…':'重试'}}</button><RouterLink v-if="task.unit_id&&task.status==='completed'" :to="`/knowledge/${task.unit_id}`" class="text-button">查看知识</RouterLink></div></div><p v-if="task.status==='failed'&&!task.can_retry&&task.file_name" class="muted task-retry-note">{{task.attempts>=task.max_attempts?'已达到重试上限，请处理原因后重新导入。':'请按失败原因修正文件后重新导入。'}}</p></li></ul></template></AsyncState></div></div>
 </AsyncState>
 </section>
 </div>
</template>
